{"name": "settled_draft_audit", "directory": "harnesses/settled_draft_audit", "hypothesis": "Auditing only mechanical defects (markup, structure, fragments of attested units, near-miss spellings) and having the pre-submit check affirm a draft it finds nothing wrong with raises the mean validation score above the 0.584 of iteration 3, mainly by recovering the single-answer samples lost to the candidate-enumeration wording (0.89 back to 0.92) and the generation samples lost to it4/it5 relation steering and over-decomposition (USPTO 0.217 back to 0.283), without losing the multi-unit gain (LawBench at or above 0.58), because no iteration measured the re-open channel repairing a sample.", "candidate_id": "e657e8d91180f70b87a6b51d0505d99dc8b16cd4a708d7ab7300157e6379efc1", "split": "val", "spec": {"limit": null, "samples": 2}, "scores": {"USPTO": {"accuracy": 0.2833333333333333, "correct": 17, "total": 60, "num_examples": 30, "aggregation": "sample_mean", "avg_f1": null, "micro_f1": null, "failed_samples": 0, "model_calls": 178, "input_tokens": 1864287, "output_tokens": 407285, "status": "ok", "successful_accuracy": 0.2833333333333333, "successful_samples": 60, "expected_samples": 60, "completion_rate": 1.0, "missing_samples": 0, "errors": [], "error_counts": {}, "partial": false, "rankable": true, "memory_context_chars": 682.4333333333333, "attempt": 2, "reused_samples": 0}, "Symptom2Disease": {"accuracy": 0.86, "correct": 86, "total": 100, "num_examples": 50, "aggregation": "sample_mean", "avg_f1": null, "micro_f1": null, "failed_samples": 0, "model_calls": 304, "input_tokens": 1797152, "output_tokens": 186975, "status": "ok", "successful_accuracy": 0.86, "successful_samples": 100, "expected_samples": 100, "completion_rate": 1.0, "missing_samples": 0, "errors": [], "error_counts": {}, "partial": false, "rankable": true, "memory_context_chars": 696.42, "attempt": 1, "reused_samples": 0}, "LawBench": {"accuracy": 0.54, "correct": 54, "total": 100, "num_examples": 50, "agg