{"name": "attested_rendering_audit", "directory": "harnesses/attested_rendering_audit", "hypothesis": "Reporting only attested renderings in the pre-submit check (a draft unit that is a piece of a reference unit, or an extension of one of its pieces, is answered with the whole unit the references render; markup is required only when the question states it; the re-open channel is deleted) while keeping the fact-based candidate wording raises the mean validation score above the 0.584 of iteration 3 - mainly by turning piece-of-a-unit drafts into whole attested units on the label task (7 of 100 samples, 0 of 160 on the other two tasks) and by removing the check's own noise (bracketed atoms demanded as markup, oscillating relation notes) - without regressing the single-label and free-form tasks.", "candidate_id": "3d44653585d4bcaa39d3d347bcd82c2f3f31c0277d683eae96e30369e22e97e2", "split": "val", "spec": {"limit": null, "samples": 2}, "scores": {"USPTO": {"accuracy": 0.25, "correct": 15, "total": 60, "num_examples": 30, "aggregation": "sample_mean", "avg_f1": null, "micro_f1": null, "failed_samples": 0, "model_calls": 181, "input_tokens": 1935438, "output_tokens": 442302, "status": "ok", "successful_accuracy": 0.25, "successful_samples": 60, "expected_samples": 60, "completion_rate": 1.0, "missing_samples": 0, "errors": [], "error_counts": {}, "partial": false, "rankable": true, "memory_context_chars": 708.3166666666667, "attempt": 2, "reused_samples": 0}, "Symptom2Disease": {"accuracy": 0.9, "correct": 90, "total": 100, "num_examples": 50, "aggregation": "sample_mean", "avg_f1": null, "micro_f1": null, "failed_samples": 0, "model_calls": 292, "input_tokens": 1878531, "output_tokens": 184010, "status": "ok", "successful_accuracy": 0.9, "successful_samples": 100, "expected_samples": 100, "completion_rate": 1.0, "missing_samples": 0, "errors": [], "error_counts": {}, "partial": false, "rankable": true, "memory_context_chars": 1085.07, "attempt": 1, "reused_samples": 0}, "L