import re
from collections import Counter

ELEMENTS = set("""H He Li Be B C N O F Ne Na Mg Al Si P S Cl Ar K Ca Sc Ti V Cr Mn Fe Co Ni Cu Zn Ga Ge As Se Br Kr Rb Sr Y Zr Nb Mo Tc Ru Rh Pd Ag Cd In Sn Sb Te I Xe Cs Ba La Ce Pr Nd Pm Sm Eu Gd Tb Dy Ho Er Tm Yb Lu Hf Ta W Re Os Ir Pt Au Hg Tl Pb Bi Po At Rn Fr Ra Ac Th Pa U Np Pu Am Cm Bk Cf Es Fm Md No Lr""".split())
TWO = {e for e in ELEMENTS if len(e) == 2}
AROMATIC = {'b': 'B', 'c': 'C', 'n': 'N', 'o': 'O', 'p': 'P', 's': 'S', 'se': 'Se', 'as': 'As', 'te': 'Te'}

def elements(smiles: str) -> Counter:
    """Heavy-atom composition of a SMILES string (element symbols only, no H)."""
    counts: Counter = Counter()
    i, n = 0, len(smiles)
    while i < n:
        ch = smiles[i]
        if ch == '[':
            j = smiles.find(']', i)
            if j < 0:
                j = n
            inner = smiles[i + 1:j]
            m = re.match(r'^\d*(\*|[A-Za-z]{1,2})', inner)
            if m:
                sym = m.group(1)
                if sym != '*':
                    if sym[0].islower():
                        counts[AROMATIC.get(sym.lower(), sym.capitalize())] += 1
                    else:
                        two = sym[0] + sym[1:2].lower()
                        counts[two if two in TWO else sym[0]] += 1
            i = j + 1
            continue
        if ch.isalpha():
            if ch.islower():
                counts[AROMATIC.get(ch, ch.upper())] += 1
                i += 1
                continue
            two = smiles[i:i + 2]
            if len(two) == 2 and two in TWO:
                counts[two] += 1
                i += 2
            else:
                counts[ch] += 1
                i += 1
            continue
        i += 1
    return counts

def parts(smiles: str):
    return [p for p in smiles.strip().split('.') if p.strip()]

def formula(c: Counter) -> str:
    return "".join(f"{k}{v if v>1 else ''}" for k, v in sorted(c.items()) if v)

TOKEN = re.compile(r'[A-Za-z0-9@+\-\[\]\(\)=#\\/%\*]{6,}')

def looks_like_formula(token: str) -> bool:
    """Conservative: mostly SMILES alphabet, at least two element symbols, balanced brackets."""
    if len(token) < 6:
        return False
    if not re.fullmatch(r'[A-Za-z0-9@+\-\[\]\(\)=#\\/%\*\.]+', token):
        return False
    if token.count('(') != token.count(')'):
        return False
    c = elements(token)
    if not c:
        return False
    letters = sum(1 for ch in token if ch.isalpha())
    if letters < 0.5 * len(token):
        return False
    return sum(c.values()) >= 4

def largest_formula_token(text: str) -> str:
    best = ''
    for m in TOKEN.finditer(text or ''):
        tok = m.group(0)
        if looks_like_formula(tok) and len(tok) > len(best):
            best = tok
    return best
