import re, sys
sys.path.insert(0, '/tmp/an')
from smi2 import elements, parts
from collections import Counter

SYMBOLS = set("""H He Li Be B C N O F Ne Na Mg Al Si P S Cl Ar K Ca Sc Ti V Cr Mn Fe Co Ni Cu Zn Ga Ge As Se Br Kr Rb Sr Y Zr Nb Mo Tc Ru Rh Pd Ag Cd In Sn Sb Te I Xe Cs Ba La Ce Pr Nd Pm Sm Eu Gd Tb Dy Ho Er Tm Yb Lu Hf Ta W Re Os Ir Pt Au Hg Tl Pb Bi Po At Rn Fr Ra Ac Th Pa U Np Pu Am Cm Bk Cf Es Fm Md No Lr""".split())
AROM = {'b', 'c', 'n', 'o', 'p', 's'}
TWO = {s for s in SYMBOLS if len(s) == 2}
TOKEN_RE = re.compile(r'[A-Za-z0-9@+\-\[\]\(\)=#\\/%\.]{6,}')

def parse_strict(token):
    """Return Counter of heavy atoms, or None if the token is not a plain chemical formula."""
    i, n, counts = 0, len(token), Counter()
    while i < n:
        ch = token[i]
        if ch == '[':
            j = token.find(']', i)
            if j < 0: return None
            inner = token[i+1:j]
            m = re.match(r'^\d*([A-Za-z]{1,2})', inner)
            if not m: return None
            sym = m.group(1)
            if sym[0].islower():
                two = sym.lower()
                if two in ('se', 'as', 'te'):
                    counts[two.capitalize()] += 1
                elif sym[0] in AROM:
                    counts[sym[0].upper()] += 1
                else:
                    return None
            else:
                two = sym[0] + sym[1:2].lower()
                if two in TWO: counts[two] += 1
                elif sym[0] in SYMBOLS: counts[sym[0]] += 1
                else: return None
            i = j + 1
            continue
        if ch.isalpha():
            if ch.islower():
                if ch in AROM:
                    counts[ch.upper()] += 1; i += 1; continue
                two = token[i:i+2]
                if two in ('Cl', 'Br', 'Si', 'Se', 'As', 'Te', 'Li', 'Na', 'Mg', 'Al', 'Ca', 'Fe', 'Zn', 'Cu', 'Sn', 'Ag', 'Au', 'Pt', 'Hg', 'Pb', 'Mn', 'Co', 'Ni', 'Cd', 'Ba'):
                    counts[two] += 1; i += 2; continue
                return None
            two = token[i:i+2]
            if two in TWO:
                counts[two] += 1; i += 2
            elif ch in SYMBOLS:
                counts[ch] += 1; i += 1
            else:
                return None
            continue
        i += 1
    return counts

def formula_token(text):
    """The longest token in the text that reads as a molecular formula, or ''."""
    best = ''
    for m in TOKEN_RE.finditer(text or ''):
        tok = m.group(0)
        if len(tok) <= len(best): continue
        c = parse_strict(tok)
        if c and sum(c.values()) >= 5 and len(c) >= 1:
            best = tok
    return best
