# Writing systems without spaces let a unit sit directly against its modifier, so an
# edge match alone is evidence there; in spaced scripts the junction has to fall on a
# word boundary, otherwise "flu" would look like a form of "reflux".
CJK = re.compile(r"[぀-ヿ㐀-䶿一-鿿豈-﫿가-힯]")

# ---------------------------------------------------------------- formula answers
# When a corpus answers with molecular formulas, one property of a candidate answer is
# checkable without any chemistry at all: a reaction's atoms all come from its
# reactants, so every element of the material the question states has to appear in the
# answer. Whether the corpus is one of those - and whether its own references have that
# property - is measured on the training references before the rule is used, so a
# corpus that answers in words never sees it.
FORMULA_TOKEN = re.compile(r"[A-Za-z0-9@+\-\[\]\(\)=#\\/%\.]{6,}")
FORMULA_ALPHABET = re.compile(r"[A-Za-z0-9@+\-\[\]\(\)=#\\/%\.]+")
