# ---------------------------------------------------------- material accounting

def material_formula(self, question: str) -> Counter | None:
    """The heavy atoms of the material the question states, when this corpus is one
    whose answers are formulas and whose question states a material."""
    if not self.formula.get("enabled"):
        return None
    token = formula_token(question)
    return parse_formula(token) if token else None

def coverage_report(self, draft: str, question: str = "") -> tuple[str, str]:
    """Whether the draft accounts for the elements of the material the question states.

    Returns ``(problem, note)``: a problem when the draft cannot be the matter's
    reactants because an element of it is missing (or because the draft is not
    written as formulas at all), a note when the accounting holds, and nothing at
    all when the corpus was not measured to be one this applies to.
    """
    material = self.material_formula(question)
    if material is None:
        return "", ""
    parts = split_formula(draft)
    if not parts:
        return (
            "- Material: the draft is empty, so it accounts for none of the heavy atoms"
            f" ({format_formula(material)}) of the material the question states.",
            "",
        )
    answer: Counter = Counter()
    unreadable: list[str] = []
    for part in parts:
        counts = parse_formula(part)
        if counts is None:
            unreadable.append(part)
        else:
            answer += counts
    if unreadable:
        shown = ", ".join(repr(part) for part in unreadable[:3])
        return (
            f"- Material: {shown} does not read as a molecular formula, and the references"
            " answer with formulas, so the answer cannot be compared with the material the"
            " question states. Write every fragment as a formula.",
            "",
        )
    missing = material - answer
    if missing:
        return (
            "- Material: the question's material has the heavy atoms"
            f" {format_formula(material)}; the draft's molecules account for"
            f" {format_formula(answer)}, so {format_formula(missing)} is missing. A"
            " reaction's atoms all come from its reactants, so a fragment that supplies"
            " those elements is missing or one of the formulas is wrong: find the"
            " disconnection that carries them and submit that answer.",
            "",
        )
    return "", (
        "- Material: the draft's molecules account for every heavy atom of the material"
        f" the question states ({format_formula(material)}). That is necessary, not"
        " sufficient - a fragment may still be the wrong one."
    )

